     <script>
       const trigger = document.querySelector(".trigger");
       const overlay = document.querySelector("#modal-overlay");
       const dialog = document.querySelector("#delete-dialog");
       const statusMessage = document.querySelector("#status-message");
       const closeButtons = document.querySelectorAll("[data-close-modal]");
       const confirmDeleteButton = document.querySelector("[data-confirm-delete]");
       const focusableSelector =
         'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
       let previousFocus;

       function getFocusableElements() {
         return Array.from(dialog.querySelectorAll(focusableSelector));
       }

       function openDialog() {
         previousFocus = document.activeElement;
         overlay.classList.add("is-open");
         const firstFocusable = getFocusableElements()[0];
         firstFocusable?.focus();
       }

       function closeDialog() {
         overlay.classList.remove("is-open");
         previousFocus?.focus();
       }

       function keepFocusInsideDialog(event) {
         if (event.key !== "Tab") {
           return;
         }

         const focusableElements = getFocusableElements();
         const firstElement = focusableElements[0];
         const lastElement = focusableElements[focusableElements.length - 1];

         if (event.shiftKey && document.activeElement === firstElement) {
           event.preventDefault();
           lastElement.focus();
         } else if (!event.shiftKey && document.activeElement === lastElement) {
           event.preventDefault();
           firstElement.focus();
         }
       }

       trigger.addEventListener("click", openDialog);

       closeButtons.forEach((button) => {
         button.addEventListener("click", closeDialog);
       });

       confirmDeleteButton.addEventListener("click", () => {
         closeDialog();
         trigger.disabled = true;
         trigger.textContent = "Image deleted";
         statusMessage.classList.remove("sr-only");
         statusMessage.textContent = "Image deleted from your library.";
       });

       overlay.addEventListener("click", (event) => {
         if (event.target === overlay) {
           closeDialog();
         }
       });

       document.addEventListener("keydown", (event) => {
         if (!overlay.classList.contains("is-open")) {
           return;
         }

         if (event.key === "Escape") {
           closeDialog();
         }

         keepFocusInsideDialog(event);
       });
     </script>
